import { Shader } from '../webgl/p5.Shader.js';
import { s as setWebGLUniformValue, e as setWebGLTextureParams, g as getWebGLUniformMetadata, h as getWebGLShaderAttributes, j as populateGLSLHooks, T as Texture } from '../rendering-BfAV84bl.js';
import { I as Image } from '../p5.Renderer-bsfqFa3q.js';
import { C as CLAMP, aa as WEBGL2, p as CORNER, B as BLEND, ab as BLUR, ac as WEBGL } from '../constants-BTsXPQC-.js';
